INSERT INTO doc_chunks (chunk_id, doc_type, source, section, content, content_hash) VALUES
('dsn-001', 'design_std', 'design_standard.md', '1. 적합성 판정 원칙', '고객 요구 사양은 항목별로 표준 모델 사양과 비교한다. 모든 항목이 기본 사양으로 충족되면 ''표준'', 옵션을 붙여 충족되면 ''파생 사양'', 옵션으로도 충족되지 않아 케이스나 모터를 바꿔야 하면 ''신규 개발''로 분류한다. 여러 모델이 후보일 때는 옵션 수가 적고 단가가 낮은 모델을 우선 추천한다.', 'df953439b4513319b0969726ad8c2c5cef08f0e4a65b9240d1af2a7d3013a106'),
('dsn-002', 'design_std', 'design_standard.md', '2. 유량 판단', '유량은 반드시 수두(압력) 조건과 함께 비교한다. 우리 모델의 유량이 고객 요구보다 크고, 우리 기준 수두가 고객 기준 수두보다 같거나 높으면 충족으로 본다. 차량용 냉각 펌프의 유량은 통상 분당 리터(L/min)로 표기하며, 시간당 리터(L/h)로 적힌 값이 1 L/min 미만으로 환산되면 단위 표기 오류일 가능성이 높으므로 고객 확인 대상이다.', 'd766bcd7d9021f79a2611563a2423bee4d6231ff2252b9c95f4148234e62703e'),
('dsn-003', 'design_std', 'design_standard.md', '3. 작동 온도', '요구 최고 온도가 표준 모델 상한을 넘으면 고온 대응 옵션(OPT-HT)을 우선 검토한다. OPT-HT는 제어칩을 고온용으로 교체해 상한을 125℃까지 올린다. 요구 온도가 125℃를 넘으면 신규 개발로 분류한다. 배터리팩 인접 장착은 고온 노출이 잦아 OPT-HT 적용을 권장한다.', '9921a4cbbadfd12cb3b31d73dd77c42e3d2723f08c6f8bb88bef8d002fd5c889'),
('dsn-004', 'design_std', 'design_standard.md', '4. 방수 등급', '방수 등급은 IP67보다 IP6K9K가 높다. IP67은 일시적 침수에 견디는 수준이고, IP6K9K는 고압·고온 세차 물줄기에도 견디는 수준이다. 고압 세차 노출 위치에 장착되는 경우 IP6K9K가 필요하며, 표준 모델이 IP67이면 방수 강화 옵션(OPT-IP9K)을 적용하고 방수 시험을 다시 수행한다.', '296ba677edacb231590ae1f8198e808f1d007449ce97fad787f99e5717eef82d'),
('dsn-005', 'design_std', 'design_standard.md', '5. 소음', '소음은 1 m 거리, 정격 유량 조건에서 측정한 값으로 비교한다. 옵션 적용으로 소음이 늘어나는 경우 늘어난 값으로 판정한다. 소음 요구를 초과하는 모델은 다른 항목이 충족되더라도 추천 대상에서 제외한다.', 'd15e368bb0382fffb19d39443490424748cb0714a537fcd5f668d37962a67009'),
('dsn-006', 'design_std', 'design_standard.md', '6. 크기와 무게', '외형 크기는 가로·세로·높이 각각이 고객 최대 치수 이내여야 한다. 무게는 옵션 추가 무게를 더한 값으로 판정한다. 크기나 무게를 줄이려면 케이스 재설계가 필요하므로 신규 개발로 분류한다.', '43a668b3467f4fd2b7ef4ce16a4f958af1b5a70b961c0c1569e6906089dcc4a9'),
('dsn-007', 'design_std', 'design_standard.md', '7. 커넥터와 냉각수', '커넥터 형상과 냉각수 종류는 설계 확정에 필요한 필수 정보다. 표준 커넥터는 4핀이며, 표준 냉각수는 에틸렌글리콜 50% 혼합액이다. 고객 사양서에 미기재되었거나 ''TBD''인 경우 표준값을 가정해 검토하되, 반드시 고객 확인 질의 목록에 포함한다.', '57f0700c0f4ff20f9a8a57b7405caf768add7de232d0a4b5dcf12d302ebde494'),
('cat-001', 'catalog', 'product_catalog.md', '1. 제품 개요', '전동식 워터펌프는 전기차의 배터리와 모터를 식히는 냉각수를 순환시키는 부품이다. 엔진 동력이 아닌 전기 모터로 돌아가므로 필요한 만큼만 냉각수를 보낼 수 있다. EWP-12 시리즈는 모두 12V 차량 전원에서 동작한다.', 'e62724c4c9a1375b37810d0f22168ec164a14f2e770ab009f0534559a27fc590'),
('cat-002', 'catalog', 'product_catalog.md', '2. EWP-12-A (소형)', '소형 차량이나 보조 냉각 라인용 모델이다. 작고 가벼우며 가격이 가장 낮지만 유량이 분당 15리터로 시리즈 중 가장 적다. 통신은 PWM만 지원한다. 주행용 배터리팩 같은 대용량 냉각에는 적합하지 않다.', 'aa56dc5c86c00689839f52fdc42201773badee03dc712dc7be49cef28573fdfe'),
('cat-003', 'catalog', 'product_catalog.md', '3. EWP-12-B (중형)', '시리즈의 주력 모델이다. 분당 25리터의 유량과 42 dB의 낮은 소음이 특징이며, LIN과 PWM 통신을 모두 지원한다. 중형 전기차 배터리 냉각에 가장 많이 적용된다. 고온 대응 옵션과 방수 강화 옵션을 붙일 수 있어 다양한 장착 환경에 대응한다.', 'b95cb8e674c38c8029d0f8f9e4fcd18fb880f66c696f161acfff231cb8076bf8'),
('cat-004', 'catalog', 'product_catalog.md', '4. EWP-12-C (대형)', '대형 차량과 고출력 모터 냉각용 모델이다. 유량이 가장 크고 기본 사양으로 125℃와 IP6K9K를 만족하지만, 모터가 커서 소음(48 dB)과 무게(0.95 kg)가 크고 가격이 가장 높다. 소음이나 무게 제한이 있는 차량에는 권장하지 않는다.', 'f46e52435ed443300b69908fc765eaae4b969c0bf4df36abf25b685ff1bca40a'),
('cat-005', 'catalog', 'product_catalog.md', '5. 옵션 OPT-HT (고온 대응)', '제어칩을 고온용으로 바꿔 작동 온도 상한을 125℃까지 높인다. 무게와 소음 변화는 없다. 배터리팩 하단처럼 열이 많은 위치에 권장한다. 고온용 제어칩은 업계 공급이 빠듯해 조달 기간이 길 수 있다.', '8021a7bea325c6e539d47eccda1330e2269ae6d021be88c614498a9e617127fb'),
('cat-006', 'catalog', 'product_catalog.md', '6. 옵션 OPT-IP9K (방수 강화)', '실링을 강화해 방수 등급을 IP67에서 IP6K9K로 높인다. 무게가 0.05 kg, 소음이 1 dB 늘어난다. 차체 하부처럼 고압 세차 물줄기가 닿는 위치에 권장한다.', '23fe839c438513eb2e044ae842fe2d9e8f344e6d3ac59d387e367c50da734704'),
('pol-001', 'policy', 'sales_policy.md', '제10조 견적 검토 원칙', '모든 견적은 기술 적합성, 부품 조달 가능성, 계약 조건을 함께 검토한 뒤 제출한다. 고객 사양서에 모순되거나 누락된 정보가 있으면 견적 제출 전에 고객에게 서면으로 확인을 요청한다.', '2df0d02987b72f18db56aec6eb5b590195a41ef8ca477b654a7b20490957a5ca'),
('pol-002', 'policy', 'sales_policy.md', '제11조 연간 가격 인하', '고객이 요구하는 연간 가격 인하율(CR)은 연 3% 이내에서 수용할 수 있다. 3%를 초과하는 경우 영업본부장의 승인이 필요하다.', 'ab32aa8a646219705775c7ddc24aa18a83511da0a9082cf9fb2c504187a62214'),
('pol-003', 'policy', 'sales_policy.md', '제12조 품질 보증 기간', '품질 보증 기간은 양산 시작일로부터 3년 또는 주행거리 100,000 km 중 먼저 도래하는 기간을 넘을 수 없다. 이를 초과하는 보증 조건은 품질본부장의 승인이 필요하며, 견적 단가에 보증 비용을 반영해야 한다.', '15365167ff419c79026476a3b044a74bd88e09decc601ccf14fc02079477f2a5'),
('pol-004', 'policy', 'sales_policy.md', '제13조 지연 배상', '납기 지연에 대한 배상 책임은 해당 계약 금액의 10%를 상한으로 한다. 배상 상한이 없거나 10%를 초과하는 조항은 수용할 수 없으며, 고객과 상한 설정을 협의해야 한다.', 'a0231d1969ce16211038a6159c4bba7b69b92b7c60ff848afc7e8cdc62fa199e'),
('pol-005', 'policy', 'sales_policy.md', '제14조 단종 통지', '주요 부품의 단종 통지 의무는 12개월 이내 기간에서 수용할 수 있다.', '8dab0f9ec8ccbae40b4fd23426c7c4013dcb90264032c6f20dc1f5f224a565ae'),
('pol-006', 'policy', 'sales_policy.md', '제15조 결제 조건', '결제 기간은 월말 마감 후 90일 이내까지 수용할 수 있다.', 'fb2608ea4a0470503d06775dd30b1bd6ce2bc9801282557e2662b3de30bb8c33'),
('pol-007', 'policy', 'sales_policy.md', '제16조 견적 마진', '견적 단가는 부품 원가 기준 마진 30% 이상이어야 한다. 마진은 (단가 − 부품 원가) ÷ 단가로 계산하며, 연간 가격 인하를 적용한 마지막 연도 단가에서도 30% 이상을 유지해야 한다. 미달 시 영업본부장의 승인이 필요하다.', 'a6261a31a62c83ac3c72f91b32c7210cde1c900a79c158c89fbb70e4ba60e2b7'),
('pol-008', 'policy', 'sales_policy.md', '제17조 견적서 형식', '견적서에는 수신처, 품목, 단가, 수량, 납기, 인도 조건, 유효기간, 조건부 사항을 모두 기재한다. 견적 유효기간은 발행일로부터 30일로 한다.', 'cdb85ba7ae8817f59f0395dc396e53a1ce72707d4a2c77387167015ff5a8f2c5'),
('pol-009', 'policy', 'sales_policy.md', '제20조 신규 공급사 부품', '처음 거래하는 공급사의 부품은 검증 시험을 통과한 뒤에만 생산에 투입한다. 대체 부품을 사용하는 경우 견적 조건에 그 사실을 명시해 고객에게 알린다.', '27d5db5cfb7411bc270fd36f64b1031c2357b38197455ec5c36f4185744c148d'),
('pol-010', 'policy', 'sales_policy.md', '제21조 대체 부품 원가', '대체 부품 사용으로 부품 원가가 오르는 경우, 증가분은 견적 단가에 포함하지 않고 견적 조건에 별도 비용으로 표시한다.', 'ec6006a658108f54384209f0bd99deec725ae14de4113fb9e7d0e5914a6c5953'),
('alt-001', 'alt_parts', 'alt_parts_criteria.md', '1. 대체 부품 검토 조건', '핵심 부품의 가용 재고가 필요 수량보다 적고, 입고 예정일이 고객 납기보다 늦으면 대체 부품을 검토한다. 대체 부품은 원래 부품과 같은 성능 등급 이상이어야 한다.', '2047ac68b94103c3f7302898f551712fba3102ae30f88a654d736e51b5542135'),
('alt-002', 'alt_parts', 'alt_parts_criteria.md', '2. 제어칩 대체', '고온용 제어칩(P-MCU-G1)의 대체품은 누리칩스의 P-MCU-G1-ALT다. 같은 고온 등급이며 핀 배치가 같아 회로 변경이 필요 없다. 다만 처음 쓰는 공급사이므로 적용 전 2주간의 검증 시험이 필요하고, 개당 원가가 300원 높다.', 'c72f4d99a4e211a13be58fe09fbe95f688b15861703a3297e5d0a6cb02966625'),
('alt-003', 'alt_parts', 'alt_parts_criteria.md', '3. 대안 비교 기준', '대안은 납기 충족 여부, 추가 원가, 검증 기간, 품질 위험 순으로 비교한다. 납기를 맞출 수 없는 대안은 다른 조건이 좋아도 우선순위에서 밀린다.', '7ae3ddd2340a49990bfcecc8c4293df228bf2c0dd2a58898c2ddd7863985de21');
